import java.util.*;

public class Main {
    static int n, mod;
    static Map<Integer, Integer>[][][] memoTable;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        mod = sc.nextInt();

        // Initialize memoTable with size [2][n+1], each element is a Map<Integer, Integer>
        memoTable = new Map[2][n + 1][2];
        for (int i = 0; i < 2; i++) {
            for (int j = 0; j <= n; j++) {
                for (int k = 0; k < 2; k++) {
                    memoTable[i][j][k] = new HashMap<>();
                }
            }
        }

        int result = solve(n, 0, 1);
        System.out.println(result % mod);
        sc.close();
    }

    static int invnum(int[] seq) {
        int count = 0;
        for (int i = 0; i < seq.length; i++) {
            for (int j = i + 1; j < seq.length; j++) {
                if (seq[i] > seq[j]) {
                    count++;
                }
            }
        }
        return count;
    }

    static int[] generatePermutation(int n, int[] current, boolean[] used, int index) {
        if (index == n) {
            return current.clone();
        }
        for (int i = 0; i < n; i++) {
            if (!used[i]) {
                used[i] = true;
                current[index] = i;
                int[] result = generatePermutation(n, current, used, index + 1);
                if (result != null) {
                    return result;
                }
                used[i] = false;
            }
        }
        return null;
    }

    static int naive(int N, int K, boolean flag) {
        List<int[]> permutationsP = generateAllPermutations(N);
        int total = 0;
        for (int[] p : permutationsP) {
            for (int[] q : permutationsP) {
                if ((comparePermutations(p, q) < 0 || !flag) && (invnum(p) - invnum(q) > K)) {
                    total++;
                }
            }
        }
        return total;
    }

    static List<int[]> generateAllPermutations(int N) {
        List<int[]> perms = new ArrayList<>();
        generatePermutationsHelper(N, new int[N], new boolean[N], perms);
        return perms;
    }

    static void generatePermutationsHelper(int N, int[] current, boolean[] used, List<int[]> perms) {
        if (current.length == N) {
            perms.add(current.clone());
            return;
        }
        for (int i = 0; i < N; i++) {
            if (!used[i]) {
                used[i] = true;
                current[current.length - N + usedCount(used) - 1] = i;
                generatePermutationsHelper(N, current, used, perms);
                used[i] = false;
            }
        }
    }

    static int usedCount(boolean[] used) {
        int count = 0;
        for (boolean b : used) {
            if (b) count++;
        }
        return count;
    }

    static int comparePermutations(int[] p, int[] q) {
        for (int i = 0; i < p.length; i++) {
            if (p[i] != q[i]) {
                return p[i] - q[i];
            }
        }
        return 0;
    }

    static int solve(int N, int K, boolean flag) {
        int flagIndex = flag ? 1 : 0;
        if (memoTable[flagIndex][N][K] != null && memoTable[flagIndex][N][K] != null) {
            return memoTable[flagIndex][N][K];
        }

        if (N == 1) {
            int res = (flag ? 0 : (K < 0 ? 1 : 0));
            memoTable[flagIndex][N][K] = res;
            return res;
        }

        int max_inv = (N * (N - 1)) / 2;

        if (K < -max_inv - 1) {
            int res = solve(N, -max_inv - 1, flag);
            memoTable[flagIndex][N][K] = res;
            return res;
        }

        if (K >= max_inv) {
            memoTable[flagIndex][N][K] = 0;
            return 0;
        }

        int total = 0;
        for (int delta = -N + 1; delta < N; delta++) {
            if (flag && delta > 0) continue;
            int weight = Math.min(N - delta, delta + N);
            int newK = K - delta;
            int res = solve(N - 1, newK, flag && delta == 0);
            total += res * weight;
            total %= mod;
        }
        memoTable[flagIndex][N][K] = total;
        return total;
    }
}

